// Curated destination content for the travel-planning services.
//
// This is general-knowledge editorial content written for this project, NOT live data. Descriptions are short and
// factual; costs are rough planning ranges per person, never quotes, and are shown to users with an "estimate"
// label. Prices change (especially in Türkiye, where lira prices move fast, so Istanbul figures are given in
// euros) and visiting rules change: users are always told to check before they go.
//
// The pictures are original illustrations generated by scripts/make-images.mjs (no photographs, so there are no
// licensing questions). To use real photographs, put licensed image files in public/img and change `image` below.
//
// The app copies this file into the database on startup (src/lib/voyage/seed.ts), so saved items and trips can
// reference places safely.

export type PlaceCategory = "landmark" | "food" | "nature" | "culture" | "shopping" | "stay" | "other";

export interface DestinationContent {
  id: string;
  name: string;
  country: string;
  summary: string;
  currency: "INR" | "TRY" | "EUR";
  image: string;
  imageAlt: string;
}

export interface PlaceContent {
  id: string;
  destinationId: string;
  name: string;
  category: PlaceCategory;
  area: string;
  description: string;
  notes?: string;
  durationMin: number;
  /** Rough per-person range in whole currency units (converted to cents when stored). */
  costMin: number;
  costMax: number;
  currency: "INR" | "EUR";
  costNote?: string;
  image: string;
  imageAlt: string;
}

export const ESTIMATE_DISCLAIMER =
  "Costs and durations are rough planning estimates written for this app, not quotes or live prices. Opening rules, tickets and prices change: check before you go.";

